Here is the commit message:
net: stmmac: selftests: Needs to check the number of
 Multicast regs

When running the MC and UC filter tests we setup a multicast address
that its expected to be blocked. If the number of available multicast
registers is zero, driver will always pass the multicast packets which
will fail the test.

Check if available multicast addresses is enough before running the
tests.

Fixes: 091810dbded9 ("net: stmmac: Introduce selftests support")
Signed-off-by: Jose Abreu <Jose.Abreu@synopsys.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug occurs because the self-tests for multicast and unicast filtering do not check if there are enough available multicast and unicast filter entries before executing the tests. If the number of available multicast registers is zero, the driver will pass multicast packets, leading to a failure in the tests that expect these packets to be blocked.

Here is the patch:

 static int stmmac_test_mcfilt(struct stmmac_priv *priv)
 {
 	unsigned char uc_addr[ETH_ALEN] = {0xf0, 0xff, 0xff, 0xff, 0xff, 0xff};
 	unsigned char mc_addr[ETH_ALEN] = {0xf1, 0xff, 0xff, 0xff, 0xff, 0xff};
 	struct stmmac_packet_attrs attr = { };
 	int ret, tries = 256;

 	if (stmmac_filter_check(priv))
 		return -EOPNOTSUPP;
 	if (netdev_uc_count(priv->dev) >= priv->hw->unicast_filter_entries)
 		return -EOPNOTSUPP;
+	if (netdev_mc_count(priv->dev) >= priv->hw->multicast_filter_bins)
+		return -EOPNOTSUPP;

 	while (--tries) {
 		/* We only need to check the mc_addr for collisions */
 		mc_addr[ETH_ALEN - 1] = tries;
 		if (stmmac_hash_check(priv, mc_addr))
 			break;
 	}

 	if (!tries)
 		return -EOPNOTSUPP;

 	ret = dev_uc_add(priv->dev, uc_addr);
 	if (ret)
 		return ret;

 	attr.dst = uc_addr;

 	/* Shall receive packet */
 	ret = __stmmac_test_loopback(priv, &attr);
 	if (ret)
 		goto cleanup;

 	attr.dst = mc_addr;

 	/* Shall NOT receive packet */
 	ret = __stmmac_test_loopback(priv, &attr);
 	ret = ret ? 0 : -EINVAL;

 cleanup:
 	dev_uc_del(priv->dev, uc_addr);
 	return ret;
 }

 static int stmmac_test_ucfilt(struct stmmac_priv *priv)
 {
 	unsigned char uc_addr[ETH_ALEN] = {0xf0, 0xff, 0xff, 0xff, 0xff, 0xff};
 	unsigned char mc_addr[ETH_ALEN] = {0xf1, 0xff, 0xff, 0xff, 0xff, 0xff};
 	struct stmmac_packet_attrs attr = { };
 	int ret, tries = 256;

 	if (stmmac_filter_check(priv))
 		return -EOPNOTSUPP;
+	if (netdev_uc_count(priv->dev) >= priv->hw->unicast_filter_entries)
+		return -EOPNOTSUPP;
 	if (netdev_mc_count(priv->dev) >= priv->hw->multicast_filter_bins)
 		return -EOPNOTSUPP;

 	while (--tries) {
 		/* We only need to check the uc_addr for collisions */
 		uc_addr[ETH_ALEN - 1] = tries;
 		if (stmmac_perfect_check(priv, uc_addr))
 			break;
 	}

 	if (!tries)
 		return -EOPNOTSUPP;

 	ret = dev_mc_add(priv->dev, mc_addr);
 	if (ret)
 		return ret;

 	attr.dst = mc_addr;

 	/* Shall receive packet */
 	ret = __stmmac_test_loopback(priv, &attr);
 	if (ret)
 		goto cleanup;

 	attr.dst = uc_addr;

 	/* Shall NOT receive packet */
 	ret = __stmmac_test_loopback(priv, &attr);
 	ret = ret ? 0 : -EINVAL;

 cleanup:
 	dev_mc_del(priv->dev, mc_addr);
 	return ret;
 }



